1	'use client';
2	
3	import type { User } from '@openfort/openfort-js';
4	import { RecoveryMethod, useSignOut, useUI, useUser } from '@openfort/react';
5	import { useEthereumEmbeddedWallet } from '@openfort/react/ethereum';
6	import {
7	  checkOpenfortUser,
8	  deleteBackendAccount,
9	  exchangeOpenfortSession,
10	  getBackendMe,
11	  logoutBackendSession,
12	  refreshBackendSession,
13	  type BackendMeResponse,
14	} from '@/lib/backend-auth-client';
15	import {
16	  QualificationQuestionnaire,
17	  type QualificationSubmission,
18	} from './qualification-questionnaire';
19	import {
20	  createContext,
21	  useCallback,
22	  useContext,
23	  useEffect,
24	  useMemo,
25	  useRef,
26	  useState,
27	  type ReactNode,
28	} from 'react';
29	import { usePathname } from 'next/navigation';
30	import { reportError } from '@/lib/error-reporting';
31	
32	type AppSessionStatus =
33	  | 'idle'
34	  | 'loading'
35	  | 'needs_onboarding'
36	  | 'creating_wallet'
37	  | 'authenticated'
38	  | 'unauthenticated'
39	  | 'error';
40	
41	type ErrorCategory = 'recoverable' | 'fatal';
42	
43	interface AuthSessionContextValue {
44	  status: AppSessionStatus;
45	  backendAccessToken: string | null;
46	  backendUser: BackendMeResponse | null;
47	  openfortUser: User | null;
48	  isOpenfortLoading: boolean;
49	  isOpenfortAuthenticated: boolean;
50	  error: string | null;
51	  errorCategory: ErrorCategory | null;
52	  retry: () => void;
53	  deleteAccount: () => Promise<void>;
54	}
55	
56	const AuthSessionContext = createContext<AuthSessionContextValue | null>(null);
57	const ONBOARDING_STORAGE_KEY = 'infrafund:onboarding-draft';
58	
59	function getErrorMessage(error: unknown) {
60	  if (error instanceof Error && error.message) {
61	    return error.message;
62	  }
63	
64	  return 'Failed to initialize your session.';
65	}
66	
67	function getUserFacingErrorMessage(message: string) {
68	  if (/failed to establish iFrame connection/i.test(message)) {
69	    return "We couldn't connect to the wallet service. Please check your connection and try again.";
70	  }
71	
72	  if (/not logged in|session/i.test(message)) {
73	    return 'Your session expired. Please sign in again.';
74	  }
75	
76	  if (/failed to fetch|networkerror/i.test(message)) {
77	    return 'We hit a network issue. Please try again.';
78	  }
79	
80	  return 'Something went wrong. Please try again.';
81	}
82	
83	function classifyError(message: string): ErrorCategory {
84	  if (
85	    /failed to fetch|networkerror|failed to establish iframe|timeout|temporarily|try again/i.test(
86	      message
87	    )
88	  ) {
89	    return 'recoverable';
90	  }
91	
92	  return 'fatal';
93	}
94	
95	function clearOnboardingDraft() {
96	  if (typeof window !== 'undefined') {
97	    window.sessionStorage.removeItem(ONBOARDING_STORAGE_KEY);
98	  }
99	}
100	
101	export function AuthSessionProvider({ children }: { children: ReactNode }) {
102	  const { user, isLoading, isAuthenticated, getAccessToken } = useUser();
103	  const { signOut } = useSignOut();
104	  const { close: closeOpenfortModal } = useUI();
105	  const { create, wallets } = useEthereumEmbeddedWallet();
106	  const openfortUserId = user?.id ?? null;
107	  const [status, setStatus] = useState<AppSessionStatus>('idle');
108	  const [backendAccessToken, setBackendAccessToken] = useState<string | null>(
109	    null
110	  );
111	  const [backendUser, setBackendUser] = useState<BackendMeResponse | null>(
112	    null
113	  );
114	  const [error, setError] = useState<string | null>(null);
115	  const [errorCategory, setErrorCategory] = useState<ErrorCategory | null>(
116	    null
117	  );
118	  const [retryCount, setRetryCount] = useState(0);
119	  const pathname = usePathname();
120	  const [pendingOnboardingAccessToken, setPendingOnboardingAccessToken] =
121	    useState<string | null>(null);
122	  const [pendingWalletCreation, setPendingWalletCreation] = useState<{
123	    accessToken: string;
124	    user: BackendMeResponse;
125	  } | null>(null);
126	  const previousAuthState = useRef(false);
127	  const bootstrapAttemptKeyRef = useRef<string | null>(null);
128	
129	  const clearSession = useCallback(() => {
130	    setBackendAccessToken(null);
131	    setBackendUser(null);
132	    setPendingOnboardingAccessToken(null);
133	    setPendingWalletCreation(null);
134	    setError(null);
135	    setErrorCategory(null);
136	    bootstrapAttemptKeyRef.current = null;
137	    clearOnboardingDraft();
138	  }, []);
139	
140	  const commitUserFacingError = useCallback((raw: string) => {
141	    const userMessage = getUserFacingErrorMessage(raw);
142	    setError(userMessage);
143	    setErrorCategory(classifyError(raw));
144	    return userMessage;
145	  }, []);
146	
147	  const baseReportExtras = useCallback(
148	    () => ({
149	      route: pathname ?? null,
150	      retryCount,
151	      openfortUserId: openfortUserId ? openfortUserId.slice(-6) : null,
152	    }),
153	    [openfortUserId, pathname, retryCount]
154	  );
155	
156	  const finalizeAuthenticatedSession = useCallback(
157	    (accessToken: string, currentUser: BackendMeResponse) => {
158	      closeOpenfortModal();
159	      setBackendAccessToken(accessToken);
160	      setBackendUser(currentUser);
161	      setPendingOnboardingAccessToken(null);
162	      setPendingWalletCreation(null);
163	      setError(null);
164	      setErrorCategory(null);
165	      clearOnboardingDraft();
166	      setStatus('authenticated');
167	    },
168	    [closeOpenfortModal]
169	  );
170	
171	  const createWalletIfNeeded = useCallback(
172	    async (accessToken: string, currentUser: BackendMeResponse) => {
173	      setBackendAccessToken(accessToken);
174	      setBackendUser(currentUser);
175	      setPendingWalletCreation({ accessToken, user: currentUser });
176	
177	      if (wallets.length > 0) {
178	        finalizeAuthenticatedSession(accessToken, currentUser);
179	        return;
180	      }
181	
182	      setStatus('creating_wallet');
183	
184	      try {
185	        await create({
186	          recoveryMethod: RecoveryMethod.AUTOMATIC,
187	        });
188	        finalizeAuthenticatedSession(accessToken, currentUser);
189	      } catch (walletError) {
190	        const rawMessage = getErrorMessage(walletError);
191	        reportError(walletError, {
192	          area: 'wallet',
193	          tags: { stage: 'create' },
194	          extra: {
195	            ...baseReportExtras(),
196	            hasExistingWallet: wallets.length > 0,
197	          },
198	        });
199	        commitUserFacingError(rawMessage);
200	        setStatus('error');
201	      }
202	    },
203	    [
204	      baseReportExtras,
205	      commitUserFacingError,
206	      create,
207	      finalizeAuthenticatedSession,
208	      wallets.length,
209	    ]
210	  );
211	
212	  const bootstrapSession = useCallback(async () => {
213	    if (!openfortUserId) {
214	      clearSession();
215	      setStatus('unauthenticated');
216	      return;
217	    }
218	
219	    setStatus('loading');
220	    setError(null);
221	
222	    try {
223	      const refreshedSession = await refreshBackendSession().catch(() => null);
224	
225	      if (refreshedSession) {
226	        try {
227	          const me = await getBackendMe(refreshedSession.access_token);
228	          finalizeAuthenticatedSession(refreshedSession.access_token, me);
229	          return;
230	        } catch {
231	          // Refresh token was valid but user is inaccessible (e.g. soft-deleted).
232	          // Clear the stale cookie and fall through to Openfort re-auth.
233	          await logoutBackendSession().catch(() => undefined);
234	        }
235	      }
236	
237	      const openfortAccessToken = await getAccessToken();
238	
239	      if (!openfortAccessToken) {
240	        throw new Error('Openfort access token is unavailable.');
241	      }
242	
243	      const checkResponse = await checkOpenfortUser(openfortAccessToken);
244	
245	      if (!checkResponse.exists) {
246	        closeOpenfortModal();
247	        setPendingOnboardingAccessToken(openfortAccessToken);
248	        setStatus('needs_onboarding');
249	        return;
250	      }
251	
252	      const loginResponse = await exchangeOpenfortSession(openfortAccessToken);
253	      const me = await getBackendMe(loginResponse.access_token);
254	
255	      finalizeAuthenticatedSession(loginResponse.access_token, me);
256	    } catch (sessionError) {
257	      reportError(sessionError, {
258	        area: 'auth',
259	        tags: { stage: 'bootstrap' },
260	        extra: baseReportExtras(),
261	      });
262	      setBackendAccessToken(null);
263	      setBackendUser(null);
264	      setPendingOnboardingAccessToken(null);
265	      setPendingWalletCreation(null);
266	      commitUserFacingError(getErrorMessage(sessionError));
267	      setStatus('error');
268	    }
269	  }, [
270	    baseReportExtras,
271	    clearSession,
272	    closeOpenfortModal,
273	    commitUserFacingError,
274	    finalizeAuthenticatedSession,
275	    getAccessToken,
276	    openfortUserId,
277	  ]);
278	
279	  const completeOnboarding = useCallback(
280	    async ({ role, type, organizationName }: QualificationSubmission) => {
281	      if (!pendingOnboardingAccessToken) {
282	        setError('Openfort access token is unavailable.');
283	        setStatus('error');
284	        return;
285	      }
286	
287	      setStatus('loading');
288	      setError(null);
289	
290	      try {
291	        const loginResponse = await exchangeOpenfortSession(
292	          pendingOnboardingAccessToken,
293	          {
294	            role,
295	            type,
296	            organization_name:
297	              type === 'organization' ? organizationName?.trim() : undefined,
298	          }
299	        );
300	        const me = await getBackendMe(loginResponse.access_token);
301	
302	        await createWalletIfNeeded(loginResponse.access_token, me);
303	      } catch (sessionError) {
304	        reportError(sessionError, {
305	          area: 'auth',
306	          tags: { stage: 'onboarding' },
307	          extra: baseReportExtras(),
308	        });
309	        commitUserFacingError(getErrorMessage(sessionError));
310	        setStatus('needs_onboarding');
311	      }
312	    },
313	    [
314	      baseReportExtras,
315	      commitUserFacingError,
316	      createWalletIfNeeded,
317	      pendingOnboardingAccessToken,
318	    ]
319	  );
320	
321	  const abandonOnboarding = useCallback(async () => {
322	    clearSession();
323	    setStatus('loading');
324	
325	    await Promise.allSettled([
326	      logoutBackendSession(),
327	      signOut().catch(() => undefined),
328	    ]);
329	
330	    clearSession();
331	    setStatus('unauthenticated');
332	  }, [clearSession, signOut]);
333	
334	  const deleteAccount = useCallback(async () => {
335	    setStatus('loading');
336	    setError(null);
337	
338	    try {
339	      if (backendAccessToken) {
340	        await deleteBackendAccount(backendAccessToken);
341	      }
342	    } catch (deleteError) {
343	      reportError(deleteError, {
344	        area: 'auth',
345	        tags: { stage: 'delete-account' },
346	        extra: baseReportExtras(),
347	      });
348	      commitUserFacingError(getErrorMessage(deleteError));
349	      setStatus('authenticated');
350	      return;
351	    }
352	
353	    await Promise.allSettled([
354	      logoutBackendSession().catch(() => undefined),
355	      signOut().catch(() => undefined),
356	    ]);
357	
358	    clearSession();
359	    setStatus('unauthenticated');
360	  }, [
361	    backendAccessToken,
362	    baseReportExtras,
363	    clearSession,
364	    commitUserFacingError,
365	    signOut,
366	  ]);
367	
368	  const retry = useCallback(() => {
369	    if (pendingWalletCreation) {
370	      void createWalletIfNeeded(
371	        pendingWalletCreation.accessToken,
372	        pendingWalletCreation.user
373	      );
374	      return;
375	    }
376	
377	    setRetryCount((count) => count + 1);
378	  }, [createWalletIfNeeded, pendingWalletCreation]);
379	
380	  useEffect(() => {
381	    if (isLoading) {
382	      setStatus((currentStatus) =>
383	        currentStatus === 'authenticated' ||
384	        currentStatus === 'needs_onboarding'
385	          ? currentStatus
386	          : 'loading'
387	      );
388	      return;
389	    }
390	
391	    if (!isAuthenticated || !openfortUserId) {
392	      clearSession();
393	      setStatus('unauthenticated');
394	      return;
395	    }
396	
397	    const bootstrapAttemptKey = `${openfortUserId}:${retryCount}`;
398	
399	    if (bootstrapAttemptKeyRef.current === bootstrapAttemptKey) {
400	      return;
401	    }
402	
403	    bootstrapAttemptKeyRef.current = bootstrapAttemptKey;
404	
405	    void bootstrapSession();
406	  }, [
407	    bootstrapSession,
408	    clearSession,
409	    isAuthenticated,
410	    isLoading,
411	    openfortUserId,
412	    retryCount,
413	  ]);
414	
415	  useEffect(() => {
416	    const signedOut =
417	      previousAuthState.current && !isLoading && !isAuthenticated;
418	
419	    previousAuthState.current = isAuthenticated;
420	
421	    if (!signedOut) {
422	      return;
423	    }
424	
425	    clearSession();
426	    setStatus('unauthenticated');
427	    void logoutBackendSession().catch(() => undefined);
428	  }, [clearSession, isAuthenticated, isLoading]);
429	
430	  const value = useMemo<AuthSessionContextValue>(
431	    () => ({
432	      status,
433	      backendAccessToken,
434	      backendUser,
435	      openfortUser: user,
436	      isOpenfortLoading: isLoading,
437	      isOpenfortAuthenticated: isAuthenticated,
438	      error,
439	      errorCategory,
440	      retry,
441	      deleteAccount,
442	    }),
443	    [
444	      status,
445	      backendAccessToken,
446	      backendUser,
447	      user,
448	      isLoading,
449	      isAuthenticated,
450	      error,
451	      errorCategory,
452	      retry,
453	      deleteAccount,
454	    ]
455	  );
456	
457	  return (
458	    <AuthSessionContext.Provider value={value}>
459	      {children}
460	      <QualificationQuestionnaire
461	        isOpen={status === 'needs_onboarding'}
462	        openfortUser={user}
463	        submitError={error}
464	        isSubmitting={status === 'loading'}
465	        onClose={() => {
466	          void abandonOnboarding();
467	        }}
468	        onSubmit={completeOnboarding}
469	        onDisqualifiedSuccess={abandonOnboarding}
470	      />
471	    </AuthSessionContext.Provider>
472	  );
473	}
474	
475	export function useAuthSession() {
476	  const context = useContext(AuthSessionContext);
477	
478	  if (!context) {
479	    throw new Error(
480	      'useAuthSession must be used within an AuthSessionProvider.'
481	    );
482	  }
483	
484	  return context;
485	}
