1	import 'server-only';
2	
3	import type { RequestMetadata } from '@/server/http';
4	import { ApiError } from '@/server/http';
5	import { getAuthConfig } from '@/server/auth/config';
6	import { signAppAccessToken, verifyAppAccessToken } from '@/server/auth/jwt';
7	import { createOpaqueToken, hashOpaqueToken } from '@/server/auth/tokens';
8	import { assertUserNotLocked } from '@/server/auth/lockout';
9	import {
10	  createSession,
11	  findSessionById,
12	  findSessionByRefreshTokenHash,
13	  revokeSession,
14	  updateSessionActivity,
15	} from '@/server/repositories/sessions';
16	import {
17	  createUser,
18	  findUserByOpenfortId,
19	  isUserUniqueConstraintError,
20	  openfortUserExists,
21	  type CreateUserRecord,
22	} from '@/server/repositories/users';
23	import {
24	  verifyOpenfortAccessToken,
25	  type VerifiedOpenfortSession,
26	} from '@/server/openfort/session';
27	
28	interface OpenfortExchangeInput {
29	  accessToken: string;
30	  firstName?: string;
31	  lastName?: string;
32	  organizationName?: string;
33	  phoneNumber?: string;
34	  email?: string;
35	  type?: string;
36	  role?: string;
37	  metadata: RequestMetadata;
38	}
39	
40	type SessionWithUser = NonNullable<
41	  Awaited<ReturnType<typeof findSessionByRefreshTokenHash>>
42	>;
43	type ActiveSession = SessionWithUser & {
44	  user: NonNullable<SessionWithUser['user']>;
45	};
46	
47	function emptyToNull(value: string | null | undefined) {
48	  const trimmed = value?.trim();
49	  return trimmed ? trimmed : null;
50	}
51	
52	function splitName(name: string | undefined | null) {
53	  const parts = name?.trim().split(/\s+/).filter(Boolean) ?? [];
54	
55	  if (parts.length === 0) return { firstName: null, lastName: null };
56	  if (parts.length === 1) return { firstName: parts[0], lastName: null };
57	
58	  return {
59	    firstName: parts[0],
60	    lastName: parts.slice(1).join(' '),
61	  };
62	}
63	
64	function normalizeUserType(type: string | undefined): CreateUserRecord['type'] {
65	  return type === 'organization' ? 'organization' : 'individual';
66	}
67	
68	function normalizeUserRole(role: string | undefined): CreateUserRecord['role'] {
69	  switch (role) {
70	    case 'project_owner':
71	    case 'investor':
72	    case 'contractor':
73	    case 'governance':
74	      return role;
75	    case 'client':
76	      return 'project_owner';
77	    case 'dao':
78	      return 'governance';
79	    default:
80	      return 'investor';
81	  }
82	}
83	
84	function assertNewUserPayload(input: OpenfortExchangeInput) {
85	  if (!input.type) {
86	    throw new ApiError('BAD_REQUEST', 'User type is required for new users.');
87	  }
88	
89	  if (!input.role) {
90	    throw new ApiError('BAD_REQUEST', 'User role is required for new users.');
91	  }
92	
93	  if (input.type === 'organization' && !emptyToNull(input.organizationName)) {
94	    throw new ApiError('BAD_REQUEST', 'Organization name is required.');
95	  }
96	}
97	
98	function buildUserRecord(
99	  input: OpenfortExchangeInput,
100	  session: VerifiedOpenfortSession
101	): CreateUserRecord {
102	  const sessionName = splitName(session.user.name);
103	
104	  return {
105	    openfortUserId: session.user.id,
106	    email: emptyToNull(input.email) ?? emptyToNull(session.user.email),
107	    firstName: emptyToNull(input.firstName) ?? sessionName.firstName,
108	    lastName: emptyToNull(input.lastName) ?? sessionName.lastName,
109	    phoneNumber:
110	      emptyToNull(input.phoneNumber) ?? emptyToNull(session.user.phoneNumber),
111	    companyName: emptyToNull(input.organizationName),
112	    type: normalizeUserType(input.type),
113	    role: normalizeUserRole(input.role),
114	  };
115	}
116	
117	async function findOrCreateUser(
118	  input: OpenfortExchangeInput,
119	  session: VerifiedOpenfortSession
120	) {
121	  const existingUser = await findUserByOpenfortId(session.user.id);
122	
123	  if (existingUser) {
124	    return { user: existingUser, created: false };
125	  }
126	
127	  assertNewUserPayload(input);
128	
129	  try {
130	    return {
131	      user: await createUser(buildUserRecord(input, session)),
132	      created: true,
133	    };
134	  } catch (error) {
135	    if (isUserUniqueConstraintError(error)) {
136	      throw new ApiError('CONFLICT', 'User already exists, please try again.');
137	    }
138	
139	    throw error;
140	  }
141	}
142	
143	function assertActiveSession(
144	  session: SessionWithUser | null
145	): asserts session is ActiveSession {
146	  if (!session || !session.user || session.user.deletedAt) {
147	    throw new ApiError(
148	      'UNAUTHORIZED',
149	      'Invalid refresh token or revoked token.'
150	    );
151	  }
152	
153	  if (session.revokedAt) {
154	    throw new ApiError(
155	      'UNAUTHORIZED',
156	      'Your session was terminated, try to login.'
157	    );
158	  }
159	
160	  const now = new Date();
161	
162	  if (session.absoluteExpiresAt <= now) {
163	    throw new ApiError(
164	      'UNAUTHORIZED',
165	      'Your session has expired. Please login again.'
166	    );
167	  }
168	
169	  if (session.activityTimeoutAt <= now) {
170	    throw new ApiError(
171	      'UNAUTHORIZED',
172	      'Your session expired due to inactivity. Please login again.'
173	    );
174	  }
175	}
176	
177	async function createAccessTokenForSession(session: ActiveSession) {
178	  const authConfig = getAuthConfig();
179	  const accessTokenExpiresAt = new Date(
180	    Date.now() + authConfig.accessTokenTtlMs
181	  );
182	  const accessToken = await signAppAccessToken(
183	    {
184	      userId: session.user.id,
185	      sessionId: session.id,
186	      kycVerified: Boolean(session.user.kycVerified),
187	      kybVerified: Boolean(session.user.kybVerified),
188	      type: session.user.type,
189	      role: session.user.role,
190	    },
191	    accessTokenExpiresAt
192	  );
193	
194	  return {
195	    userId: session.user.id,
196	    accessToken,
197	    accessTokenExpiresAt,
198	  };
199	}
200	
201	export async function checkOpenfortUser(accessToken: string) {
202	  const session = await verifyOpenfortAccessToken(accessToken);
203	
204	  return {
205	    exists: await openfortUserExists(session.user.id),
206	  };
207	}
208	
209	export async function exchangeOpenfortSession(input: OpenfortExchangeInput) {
210	  const openfortSession = await verifyOpenfortAccessToken(input.accessToken);
211	  const { user, created } = await findOrCreateUser(input, openfortSession);
212	
213	  if (!created) {
214	    await assertUserNotLocked(user.id);
215	  }
216	
217	  const refreshToken = createOpaqueToken();
218	  const authConfig = getAuthConfig();
219	  const now = Date.now();
220	  const accessTokenExpiresAt = new Date(now + authConfig.accessTokenTtlMs);
221	  const session = await createSession({
222	    userId: user.id,
223	    refreshTokenHash: hashOpaqueToken(refreshToken),
224	    metadata: input.metadata,
225	    activityTimeoutAt: new Date(now + authConfig.activityTimeoutMs),
226	    absoluteExpiresAt: new Date(now + authConfig.absoluteSessionTtlMs),
227	  });
228	  const accessToken = await signAppAccessToken(
229	    {
230	      userId: user.id,
231	      sessionId: session.id,
232	      kycVerified: Boolean(user.kycVerified),
233	      kybVerified: Boolean(user.kybVerified),
234	      type: user.type,
235	      role: user.role,
236	    },
237	    accessTokenExpiresAt
238	  );
239	
