3	export const refreshTokenCookieName = 'refresh_token';
4	
5	const defaultAccessTokenTtlMs = 15 * 60 * 1000;
6	const defaultActivityTimeoutMs = 15 * 60 * 1000;
7	const defaultAbsoluteSessionTtlMs = 7 * 24 * 60 * 60 * 1000;
8	
9	function readOptionalString(name: string) {
10	  const value = process.env[name]?.trim();
11	  return value ? value : undefined;
12	}
13	
14	function parseDuration(value: string | undefined, fallbackMs: number) {
15	  if (!value) return fallbackMs;
16	
17	  const match = value.match(/^(\d+)(ms|s|m|h|d)?$/i);
18	  if (!match) return fallbackMs;
19	
20	  const amount = Number(match[1]);
21	  const unit = match[2]?.toLowerCase() ?? 'ms';
22	  const multipliers: Record<string, number> = {
23	    ms: 1,
24	    s: 1000,
25	    m: 60 * 1000,
26	    h: 60 * 60 * 1000,
27	    d: 24 * 60 * 60 * 1000,
28	  };
29	
30	  return amount * multipliers[unit];
31	}
32	
33	function readDuration(name: string, fallbackMs: number) {
34	  return parseDuration(readOptionalString(name), fallbackMs);
35	}
36	
37	export function getAuthConfig() {
38	  return {
39	    accessTokenTtlMs: readDuration(
40	      'APP_JWT_ACCESS_TOKEN_TTL',
41	      defaultAccessTokenTtlMs
42	    ),
43	    activityTimeoutMs: readDuration(
44	      'APP_AUTH_SESSION_ACTIVITY_TIMEOUT',
45	      defaultActivityTimeoutMs
46	    ),
