async () => {
  // Test 1: simple fetch with default referrer policy
  const r1 = await fetch('https://embed.openfort.io/iframe/pk_test_74e8ce8c-e030-5c05-bdfe-e97489253b0c', {
    method: 'GET',
    mode: 'no-cors'
  }).catch(e => ({ error: String(e) }));

  // Test 2: with explicit referrer
  const r2 = await fetch('https://embed.openfort.io/iframe/pk_test_74e8ce8c-e030-5c05-bdfe-e97489253b0c', {
    method: 'GET',
    referrer: 'http://localhost:3000/',
    referrerPolicy: 'unsafe-url'
  }).then(r => ({ status: r.status })).catch(e => ({ error: String(e) }));

  // Inspect referrer policy in effect
  return {
    documentReferrer: document.referrer,
    documentReferrerPolicy: document.referrerPolicy,
    test1: r1?.type ?? r1,
    test2: r2,
  };
}

